// Parse Claude's JSON. The assistant turn was prefilled with "{", so the API
// returns the JSON WITHOUT its opening brace — we prepend it back here.
const res = $input.first().json;
const modelUsed = res.model || 'claude-haiku-4-5';

let raw = '';
if (res.content && res.content[0] && typeof res.content[0].text === 'string') {
  raw = res.content[0].text;
}

// Prepend the consumed "{", strip any stray code fences, trim.
let jsonText = ('{' + raw).replace(/```json/gi, '').replace(/```/g, '').trim();

try {
  const parsed = JSON.parse(jsonText);
  return [{
    json: {
      decision: parsed.decision,
      reasoning: parsed.reasoning,
      actions: Array.isArray(parsed.actions) ? parsed.actions : [],
      low_stock_items: Array.isArray(parsed.low_stock_items) ? parsed.low_stock_items : [],
      suggested_reorder_quantity: (parsed.suggested_reorder_quantity === undefined ? null : parsed.suggested_reorder_quantity),
      model_used: modelUsed,
      raw_response: jsonText
    }
  }];
} catch (err) {
  return [{
    json: {
      parse_error: true,
      decision: 'parse_error',
      reasoning: 'Could not parse Claude output as JSON: ' + err.message,
      actions: [],
      low_stock_items: [],
      suggested_reorder_quantity: null,
      model_used: modelUsed,
      raw_response: raw
    }
  }];
}
